/bin/bash -lc "sed -n '1,260p' /run/contract/study-target.json; printf '\\n--- article metadata ---\\n'; sed -n '1,240p' /study/study.json; printf '\\n--- headings/results snippets ---\\n'; rg -n -i -C 3 'abstract|Methods|Materials|air pollution|pollutant|PM2|ozone|NO2|outcome|regression|Table [0-9]|exposure|cohort|hospital|mortality|death|covariate' /study/article.txt | sed -n '1,360p'; printf '\\n--- supplement extract ---\\n'; python - <<'PY'
from docx import Document
p='/study/supplements/12940_2021_784_MOESM1_ESM.docx'
d=Document(p)
for para in d.paragraphs:
 print(para.text)
for table in d.tables:
 for row in table.rows:
  print('\\t'.join(c.text for c in row.cells))
PY"

/bin/bash -lc "sed -n '1,260p' /run/contract/study-target.json; printf '\\n--- article metadata ---\\n'; sed -n '1,240p' /study/study.json; printf '\\n--- headings/results snippets ---\\n'; rg -n -i -C 3 'abstract|Methods|Materials|air pollution|pollutant|PM2|ozone|NO2|outcome|regression|Table [0-9]|exposure|cohort|hospital|mortality|death|covariate' /study/article.txt | sed -n '1,360p'; printf '\\n--- supplement extract ---\\n'; python - <<'PY'
from docx import Document
p='/study/supplements/12940_2021_784_MOESM1_ESM.docx'
d=Document(p)
for para in d.paragraphs:
 print(para.text)
for table in d.tables:
 for row in table.rows:
  print('\\t'.join(c.text for c in row.cells))
PY"

/bin/bash -lc "sed -n '87,220p' /study/article.txt; sed -n '315,380p' /study/article.txt; sed -n '470,495p' /study/article.txt; python3 - <<'PY'
from docx import Document
p='/study/supplements/12940_2021_784_MOESM1_ESM.docx'
d=Document(p)
for para in d.paragraphs:
 if para.text.strip(): print(para.text)
for j,table in enumerate(d.tables):
 print('\\nTABLE',j+1)
 for row in table.rows:
  print('\\t'.join(c.text.replace('\\n',' ') for c in row.cells))
PY
printf '\\n--- schemas ---\\n'; sed -n '1,300p' /run/contract/analysis-handoff.schema.json; printf '\\n--- caps ---\\n'; sed -n '1,240p' /run/contract/public-source-capabilities.json"

/bin/bash -lc "sed -n '87,220p' /study/article.txt; sed -n '315,380p' /study/article.txt; sed -n '470,495p' /study/article.txt; python3 - <<'PY'
from docx import Document
p='/study/supplements/12940_2021_784_MOESM1_ESM.docx'
d=Document(p)
for para in d.paragraphs:
 if para.text.strip(): print(para.text)
for j,table in enumerate(d.tables):
 print('\\nTABLE',j+1)
 for row in table.rows:
  print('\\t'.join(c.text.replace('\\n',' ') for c in row.cells))
PY
printf '\\n--- schemas ---\\n'; sed -n '1,300p' /run/contract/analysis-handoff.schema.json; printf '\\n--- caps ---\\n'; sed -n '1,240p' /run/contract/public-source-capabilities.json"

